<script setup lang="ts">
import {computed} from 'vue'
const props=defineProps<{host?:Record<string,any>,endpoints:string[],egress:string[]}>(),emit=defineEmits<{endpoints:[string[]],egress:[string[]]}>()
const ips=computed(()=>Array.from(new Set([props.host?.address,...(props.host?.reported_addresses??[])])).filter((x):x is string=>typeof x==='string'&&(/^(\d{1,3}\.){3}\d{1,3}$/.test(x)||x.includes(':'))&&!x.startsWith('fe80:')))
const stale=computed(()=>props.endpoints.filter(x=>!ips.value.includes(x)))
const v4=computed(()=>ips.value.find(x=>!x.includes(':'))),v6=computed(()=>ips.value.find(x=>x.includes(':')))
function endpoint(ip:string,checked:boolean){emit('endpoints',checked?[...props.endpoints.filter(x=>x.includes(':')!==ip.includes(':')),ip]:props.endpoints.filter(x=>x!==ip))}
function selectEgress(f:string,checked:boolean){emit('egress',checked?[...props.egress,f]:props.egress.filter(x=>x!==f))}
</script>
<template><fieldset class="network-fields"><legend>IP 地址与出站</legend><p class="muted">发布 IP 随主机同类型地址变化同步；双选会生成 IPv4 / IPv6 两个节点。每种类型最多一个地址。手动输入连接地址会取消发布 IP 选择，保留独立域名或 NAT 地址。</p><div class="choice-list"><label v-for="ip in ips" :key="ip"><input type="checkbox" :checked="endpoints.includes(ip)" @change="endpoint(ip,($event.target as HTMLInputElement).checked)">{{ip.includes(':')?'IPv6':'IPv4'}} · {{ip}}</label><label v-if="!v4"><input type="checkbox" disabled>无 IPv4（主机未回报）</label><label v-if="!v6"><input type="checkbox" disabled>无 IPv6（主机未回报）</label><label v-for="ip in stale" :key="ip"><input type="checkbox" checked @change="endpoint(ip,false)">旧发布 IP · {{ip}}（当前主机未回报，可取消或选择同类型新 IP 替换）</label></div><p v-if="stale.length" role="status" class="form-note">旧发布 IP 仍保存在配置中。选择新的同类型 IP 会替换旧值；也可直接修改下方连接地址，切换到手动发布。</p><h4>VPS 出站地址类型</h4><div class="choice-list"><label><input type="checkbox" :checked="egress.includes('ipv4')" :disabled="!v4" @change="selectEgress('ipv4',($event.target as HTMLInputElement).checked)">IPv4</label><label><input type="checkbox" :checked="egress.includes('ipv6')" :disabled="!v6" @change="selectEgress('ipv6',($event.target as HTMLInputElement).checked)">{{v6?'IPv6':'无 IPv6'}}</label></div><p class="form-note">未选择使用系统默认。单选限制该类型；双选按选择顺序优先解析。Xray 双栈在首选类型解析无结果时回退，连接失败时不会切换。设置出站策略需要 Agent 0.12.0；IP 存在不代表外网路由已连通。地址同步后客户端需更新订阅。</p></fieldset></template>
<style scoped>.network-fields{border:1px solid var(--line);border-radius:12px;padding:16px;margin:18px 0}h4{margin-bottom:8px}</style>
